import { q } from '@actual-app/core/shared/query';

import { AccountInternal } from './Account';

type Instance = InstanceType<typeof AccountInternal>;

function makeInstance(state: Partial<Instance['state']>) {
  const setShowReconciled = vi.fn();
  const instance = new AccountInternal({
    accountId: 'account-1',
    accounts: [{ id: 'account-1' }],
    dateFormat: 'MM/dd/yyyy',
    showReconciled: false,
    setShowReconciled,
  } as unknown as ConstructorParameters<typeof AccountInternal>[0]);

  // Apply state synchronously so setState callbacks run right away.
  instance.setState = ((
    update: Partial<Instance['state']>,
    callback?: () => void,
  ) => {
    instance.state = { ...instance.state, ...update };
    callback?.();
  }) as Instance['setState'];
  instance.state = { ...instance.state, ...state };

  const updateQuery = vi.fn();
  instance.updateQuery = updateQuery;
  instance.paged = { unsubscribe: vi.fn() } as unknown as Instance['paged'];

  return { instance, updateQuery, setShowReconciled };
}

describe('AccountInternal toggle-reconciled', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  test('keeps the search applied after toggling', async () => {
    const { instance, updateQuery, setShowReconciled } = makeInstance({
      search: 'grocery',
      showReconciled: false,
    });
    instance.rootQuery = instance.currentQuery = q('transactions');

    await instance.onMenuSelect('toggle-reconciled');
    vi.runAllTimers();

    expect(setShowReconciled).toHaveBeenCalledWith(true);
    expect(instance.state.showReconciled).toBe(true);
    expect(instance.state.search).toBe('grocery');

    expect(updateQuery).toHaveBeenCalledTimes(1);
    const [query, isFiltered] = updateQuery.mock.calls[0];
    expect(isFiltered).toBe(true);
    // The search narrows the query beyond the plain transactions query.
    expect(JSON.stringify(query.serialize())).not.toEqual(
      JSON.stringify(q('transactions').serialize()),
    );
    expect(JSON.stringify(query.serialize())).toContain('grocery');
  });

  test('keeps the current sort and filters when toggling without a search', async () => {
    const { instance, updateQuery } = makeInstance({
      search: '',
      showReconciled: true,
      filterConditions: [{ field: 'amount', op: 'gt', value: 0 }],
    });
    instance.rootQuery = q('transactions');
    const sortedFilteredQuery = q('transactions')
      .filter({ amount: { $gt: 0 } })
      .orderBy({ date: 'desc' });
    instance.currentQuery = sortedFilteredQuery;

    await instance.onMenuSelect('toggle-reconciled');
    vi.runAllTimers();

    expect(instance.state.showReconciled).toBe(false);
    expect(updateQuery).toHaveBeenCalledTimes(1);
    expect(updateQuery).toHaveBeenCalledWith(sortedFilteredQuery, true);
  });
});
